INSERT INTO player_duties VALUES(1,1,'2025-26',1,'GK','짧은 빌드업 개시(압박 아래에서도 풀백·CB 배급 — 고정 원칙), 박스 장악, 미드블록 뒤 페널티 폭 전체 커버. 스위핑은 상시가 아니라 상황부.','실측(3경기): 중심이 자기 골라인에 고정(x~10.1-10.5), 좌우로는 중앙(y~46-53). 박스 폭 전체의 얕고 넓은 커버. 오프라인 이탈 최대치는 경기가 요구했을 때 1경기뿐 — 스위핑은 상황부. 액션 볼륨 높음(한 경기 74+).','HIGH — 딥 베이스+전폭 커버+빌드업 관여가 임무와 정확히 일치. 미드블록을 깨는 과잉 스위핑 증거 없음.','빌드업 임무에는 gk_sweeper/Build-Up이 맞고, 실측 깊이는 스위핑이 상황부임을 말하므로 경기 변형에서 Balanced 포커스 허용(로저스 CAM 프리셋에서 사용). [확정 2026-07-05: gk_ballplaying/Build-Up — 숙련도 타이브레이커. 골라인+빌드업 화해.]','appearances player_id=1 ranks 1-3 (measured); tactic_observations build_up','MEDIUM-HIGH — heatmaps HIGH (API-measured); note top-3 selection bias (best matches only).');
INSERT INTO player_duties VALUES(2,1,'2025-26',2,'RB','수비 우선 라이트백: 상대 윙어 봉쇄, 우측 터치라인 폭 유지, 좌 풀백과 한 명씩만 전진(기본 규칙), 지배 시 늦은 박스 진입.','실측(3경기): 매 경기 y~15-20 — 절대 안쪽으로 안 들어옴. 측면 높이는 임무 따라 가변: 수비형(수비 38%/미들 42%), 균형(29%/41%), 높이 상주(미들 46%/공격 32%) 각 1경기.','HIGH — 폭 규율은 절대적. 높이는 ''한 명씩 전진'' 규칙 예측대로 게임플랜별 조절.','fb_fullback/Versatile(최적)이 높이 조절에 부합. 봉쇄 임무(예: 리버풀전, 로저스 CAM 프리셋)에는 Defend 포커스 전환.','appearances player_id=2 ranks 1-3 (measured); tactic_observations in_possession/modulation','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(3,1,'2025-26',3,'RCB','우측 듀얼·공중볼 앵커, 전진한 캐시 배후 커버, 소유 시 볼 들고 우중앙 미드필드로 스텝업, 파포스트 세트피스 위협.','실측(3경기): 수비|우측 35-50% 핵심, 미들|중앙 20-34% 스텝인(포레스트전 최대, 최고 라인 경기서 x중심 33.6). 공격 3분의1 스파이크는 세트피스뿐(볼로냐 원정 헤더 골).','HIGH — 임무와 발자국의 교과서적 일치. 스텝아웃 캐리는 서사가 아니라 실측된 것.','cb_defender/Balanced 확인 — 실측 미들 스텝인이 순수 스토퍼 Defend보다 Balanced를 지지. [이벤트 스탯 2026-07-02: 패스 96%(스쿼드 최고) — BPD 3축 충족, 최적을 cb_bpd/Build-Up으로 승급.]','appearances 72-74 (measured); tactic_observations defence','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(4,1,'2025-26',4,'LCB','좌측 볼 플레잉 CB: 캐리·패스로 좌 하프스페이스 전진, 디뉴/마첸과 인버티드 좌측 공격에 공급, 상대를 눌러둘 때 미드필드 진입. 세트피스 박스 진입.','실측(3경기): y~67-71 좌중앙 상수. 깊이는 지배도에 비례: 볼로냐전 딥(자기 진영 70%), 풀럼(미들 54%)·포레스트(x 최대 97 — 헤더+PK 유도)선 미들 스텝인. 오픈플레이 공격 3분의1 볼륨은 0에 가까움.','HIGH — 전진은 좌중앙 채널을 ''올라가며'' 일어남 — 정확히 BPD 임무. 좌측 채널을 벗어나지 않음.','cb_bpd/Build-Up 명백히 확인.','appearances player_id=4 ranks 1-3 (measured); tactic_observations build_up','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(5,1,'2025-26',5,'LB','공수 겸장 레프트백: 인버티드 공격을 위한 좌측 터치라인 폭 유지(로저스 컷인·디뉴 폭), 캐시와 반대로 한 명씩 전진, 크로스·컷백 배달. 수비 복귀와 공격 산출의 균형.','실측(3경기): 3경기 모두 y~82-84 터치라인 밀착. 평균 높이 45→51→53, 공격 3분의1 비중 21%→35%→41%로 임무별 가변. 52-86터치, 큰 왕복 볼륨. 보강 2026-07-02(팰리스 원정 7.7·스퍼스 원정 6.9 포함 5그리드): 높이가 홈/원정 안정적 — 평균 전진 홈 ~49.6 vs 원정 ~47.9(툴 y). 원정에서도 공격 3분의1 볼륨 유지.','HIGH — 폭 상수·높이 가변. 리버풀전 컷백 어시스트(로저스 골)가 임무 수행의 정점.','균형용은 fb_fullback/Versatile(최적), 실측 움직임은 fb_att_wb/Support에 최적합(코사인 0.89). 마첸과의 핵심 대비: 디뉴는 홈이든 원정이든 같은 왕복 프로필 — 게임플랜이 장소·상대 변동을 견뎌야 할 때 그를 선택.','appearances player_id=5 ranks 1-3 (measured); tactic_observations in_possession','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(6,1,'2025-26',6,'LB','공격형 레프트백 변형(디뉴의 균형형과 대비): 높고 넓은 시작 위치, 좌 하프스페이스로 바이라인까지 침투, 인버티드 좌윙어와 오버로드. 좌측 수비 레인 전체는 여전히 책임.','실측(3경기): 평균 높이 44-56/100(일반 FB 훨씬 이상), y~81-83. 매 경기 좌측 채널 엔드투엔드 — 자기 박스에서 상대 바이라인까지. 마카비전 바이라인 런 골. 브렌트포드전 115히트·100터치·6태클. 보강 2026-07-02(뉴캐슬 원정 7.1·페예노르트 원정 7.0 포함 5그리드): 높이가 홈/원정 요동 — 평균 전진 홈 ~51.6 vs 원정 ~43.6, 스쿼드 최대 홈/원정 격차. 하이앤와이드는 실재하나 주로 홈 현상 — 원정에선 딥으로 수렴.','HIGH — 측정된 수비수 중 가장 전진형 발자국이면서 왕복 볼륨이 수비 레인 방기가 아님을 증명.','홈/지배 임무용 fb_att_wb/Attack 유지. 디뉴와의 핵심 대비: 원정·강한 윙어 상대면 실측 프로필이 평범한 딥 LB로 붕괴 — 그땐 디뉴 우선 또는 마첸 Defend 변형.','appearances player_id=6 ranks 1-3 (measured); tactic_observations modulation axis 4','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted.');
INSERT INTO player_duties VALUES(7,1,'2025-26',12,'LDM','피벗 앵커: 백4 스크린, 중앙 우측에 위치(오나나/틸레만스가 좌측 레인), 통제된 순환, 전진하는 좌측 커버. 간헐적 전진 캐리.','실측: 26경기 평균위치 스윕 y=42.6(우 12/중 12/좌 2) — 우중앙 피벗. 10월부터 11연승 내내 우측 고정, 1월 부상까지. 깊이: 지배 경기 x 39-54 하프라인 컨트롤러(상위3 히트맵 미들 47-66%), 접전에선 더 딥. 탈편향 2026-07-02: 첼시 원정(6.7)·리버풀 원정 0-2패(6.3) 추가 — 포지션-순수 집계 여전히 하프라인(툴 y≈45), 최근접 커널 dm_dlp/Roaming(0.83) vs dm_holding/Ball-Winning(0.58). 추가: 피벗 사이드가 시즌 중 전환 — 8월~10월중순 좌측(y~55-65), 스퍼스 원정 승(10/19)부터 우측(y~30-44) 고정.','HIGH(스크린·순환). ''깊이 앉는 앵커'' 서사는 탈편향 표본으로 기각 — 우중앙 딥라잉 플레이메이커다. 사이드 전환(좌→우, 10월 중순)은 연승기 피벗 기하와 동시.','RDM 슬롯 확인. 역할 갱신: dm_dlp 프로필(kind=role: 0.83). optimal은 처방적 안전선 dm_holding/Ball-Winning 유지. [이벤트 스탯 2026-07-02: dlp 경향 반전 — 기능은 스쿼드 최고 볼위닝(듀얼승 8.4·인터셉트 3.0/경기)에 높은 패스량(56/경기·87%). 움직임=dlp, 기능=holding의 하이브리드. 기능 근거로 dm_holding/Ball-Winning 유지.] [확정 2026-07-05: dm_holding/Ball-Winning — 숙련 동률 시 기능 축 우선. A/B 종결.]','appearances player_id=12 ranks 1-3 (measured); tactic_observations modulation','HIGH on side and depth — settled by 26-match avg-position sweep + away/loss grid samples (2026-07-02).');
INSERT INTO player_duties VALUES(8,1,'2025-26',16,'ST','원톱 3중 임무: ⑴ 와이드 딜리버리를 위한 중앙 박스 점유 ⑵ 내려와 연결— 컷인하는 로저스/맥긴에 레이오프 ⑶ 전환 배출구로 뒷공간 채널 런(10번 공간을 열기 위한 와이드 드리프트).','실측(3경기): 세 임무가 경기 유형별로 깨끗이 분리 — 선덜랜드: 순수 중앙 박스 점유(와이드 딜리버리 헤더 2), 리버풀: 중앙 박스+로저스와 좌측 링크, 맨시티(원정 역습 임무): 더 딥한 평균, 하프라인~박스 전환 레인, 중앙-우측 채널 버스트.','HIGH — 발자국이 게임플랜별로 재편되면서 득점 산출은 상수(3경기 각 2골). 시스템에서 가장 임무 순응적인 공격수.','st_advanced/Versatile 정확히 확인 — 박스 점유/링크/채널 런 삼위일체는 Attack(순수 포처)보다 Versatile이 담는다. [샷맵 2026-07-02: 103슛/38이벤트, 박스 내 84%, 6야드 24, 헤더 19, xG/슛 0.19 — 순수 박스 점유 도착 프로필.]','appearances player_id=16 ranks 1-3 (measured); tactic_observations in_possession','MEDIUM-HIGH — heatmaps HIGH; top-3 bias noted but the three matches happen to span three distinct game types (home rout, home clash, away counter), which mitigates it.');
INSERT INTO player_duties VALUES(9,1,'2025-26',13,'CAM','중앙 10번: 피벗과 공격 연결, 늦은 박스 진입, 미들서드 캐리. 비소유 시 왓킨스와 함께 압박(4-4-2 블록).','최다 기용: 21선발 1759분 평균 7.10, 최고 8.5(리즈 원정) — 그의 최고 per-90 축. 리버풀 4-2 실측 히트맵: 로밍형 중앙 크리에이터, 골+어시스트.','HIGH — 최대 분량을 최고 평균 산출로 소화.','부엔디아의 10번 대안으로 cam_playmaker/Roaming 가용. 그의 LW 슬롯을 말렌/산초 로테이션에 열어줌.','player_match_positions player_id=13; appearances Liverpool CAM (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(10,1,'2025-26',13,'LW','인버티드 좌측 포워드: 높은 좌측 유지, 오른발 컷인, 중거리 슛, 오버래핑 디뉴/마첸과 연계.','최고 천장 포지션: 13선발 평균 6.91이지만 시즌 최고 2경기(웨스트햄 9.3·선덜랜드 홈 9.0)와 실측 피크(8.84/8.46)가 전부 여기. 붐-오어-콰이엇 프로필: CAM보다 바닥은 낮고 천장은 높다.','빅게임 HIGH. 평균 산출은 CAM보다 비일관.','최대 천장용은 w_insidefwd/Attack(현 최적)이 맞음. 일관성을 원하면 CAM 기용 + 자연 LW 배치.','player_match_positions player_id=13; appearances 8.84/8.46 LW heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(11,1,'2025-26',13,'RM','우측 공격수(비상·로테이션): 우측 폭 유지, 좌측 채널로 컷인.','최약 축: 8선발 평균 6.33 — 스쿼드 표본 내 (선수,포지션) 쌍 최악. 최고 RM 실측(맨유 원정 7.3)조차 측면을 버리고 중앙 터치를 찾아다님 — 인버티드 윙어 무기가 우측으로 이식되지 않는다.','LOW — 수치와 움직임 패턴 모두 이 기용이 낭비라고 말함.','어떤 프리셋에서도 로저스를 우측에 배치하지 말 것. 우측 커버 필요 시 맥긴·게상 우선.','player_match_positions player_id=13; appearances match_id=45 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(12,1,'2025-26',14,'LW/left-10','전진 좌중앙 크리에이터: 좌 하프스페이스와 중앙 사이 자유 이동, 키패스, 세트피스 킥. 4-4-2 블록에서 세컨드 스트라이커로 압박.','최다 기용: 21선발 1541분 평균 6.90 — 그리고 천장: 9.4(포레스트 4강)·8.5(본머스)·8.3(EL 결승) 전부 좌중앙 실측(중심 y64-72). 언론의 ''우측 드리프트 10번'' 서사는 사망: 시즌 우측 선발 단 2회.','녹아웃·빅매치 HIGH. 리그 시즌 일관성은 보통.','최적 행은 10번(cam_playmaker/Roaming) — 단 자유 역할이 좌편향으로 이해될 때만 정확. 엄격한 셋업에선 AML/좌10번 슬롯. 절대 우측 배치 금지.','player_match_positions player_id=14; appearances 75-77 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(13,1,'2025-26',14,'pivot-left','더 깊은 좌측 8번: 왕복 셔틀, 좌 하프스페이스 볼 순환, 늦은 박스 진입.','신뢰성 포지션: 8선발 평균 7.09 — 그의 선발당 최고 평균, 전진 역할보다 높음. 실측(뉴캐슬 원정 7.9·골): 수비|좌 31%+미들|좌 22% 진짜 수비 작업(4태클)에 박스 도착까지.','HIGH — 조용히 가장 일관된 기용.','게임: 로테이션 셋업에서 CM/좌8번 Balanced 또는 Build-Up이 정당한 2차 매핑 — 창의성 유지에 수비 존재감 추가.','player_match_positions player_id=14; appearances match_id=18 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(14,1,'2025-26',10,'RM','미드필드 4의 우측: 블록에서 폭 유지, 소유 시 하프스페이스 런, 상대 LB 압박, 파포스트 도착.','최다 기용: 21선발 1672분 평균 7.08, 최고 8.7(포레스트 4강)+8.6/8.5 — 천장 경기가 전부 여기. 실측 히트맵: 우 하프스페이스·채널, 박스 가장자리 도착(득점).','HIGH — 연승 팀에서 주장의 정의적 역할.','기반 XI용 wm_widemid/Support(현 최적) 확인. [이벤트 스탯 2026-07-02: 최적 wm_insidefwd/Balanced로 승급.] [샷맵 2026-07-02: 46슛 중 헤더 0·6야드 1, 평균 17.1m, 골대 좌측 편향 — 박스 스트라이커가 아니라 박스 가장자리 인사이드 포워드 도착. 승급 보강.]','player_match_positions player_id=10; appearances McGinn RM heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(15,1,'2025-26',10,'pivot-right','더블 피벗 우측(딥 8번): 왕복 엔진, 압박 탈출 캐리, RB 지원, 늦은 도착.','최고 평균 포지션: 7선발 평균 7.30 — RM 평균보다 높고 험지 원정에 집중. 실측(페예노르트 원정 7.9·골): 전장 왕복 커버(x3-99), 미들|중앙+미들|우측 핵심에 실제 회수 작업.','HIGH — 폭을 통제와 맞바꾸면 평점이 오른다.','정당한 2차 매핑: 원정/수비 변형 프리셋에서 자연 DM 대신 CM-우측/DM 인접 역할 Balanced 포커스.','player_match_positions player_id=10; appearances match_id=3 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(16,1,'2025-26',10,'CAM','중앙 10번(로테이션): 라인 사이 연결자, 세컨드 스트라이커 압박.','4선발 평균 6.90. 실측(웨스트햄 홈 7.8·골): 정중앙 연결자(미들|중앙 35%), 컴팩트 x29-87 — 기능하지만 그의 압박·박스 쇄도 가치는 우측 와이드나 우측 딥에서 더 산다.','MEDIUM — 쓸 만하나 부가가치 없음.','선호하지 말 것. 부엔디아·로저스 둘 다 불가할 때만.','player_match_positions player_id=10; appearances match_id=22 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(17,1,'2025-26',9,'pivot-left','피벗 좌측 딥라잉 플레이메이커: 딥에서 템포 지휘, 전진 패스, 늦은 박스 진입(EL 결승 득점).','최다·최고 포지션: 11선발 평균 7.32(+중앙 10선발 7.24 — 레인 경계에 걸친 같은 역할, 합산 21선발 ~7.28), 최고 8.4(EL 결승·골). 실측: 좌중앙의 더 깊은 배급자.','HIGH — 카마라 부상기 연승 팀의 템포 원천. 시즌 최고 경기들이 여기서 나옴.','dm_dlp/Build-Up(현 벤치 매핑) 확인 — 수정된 피벗 기하에서 카마라(RDM)의 1순위 LDM 파트너. [이벤트 스탯 2026-07-02: 기능으로 메트로놈 검증 — 패스 87%·xA 0.30(스쿼드 최고)·xG 0.12: 딥 크리에이터, 3축 확인.] [샷맵 2026-07-02: 30슛 중 헤더 5+6야드 4 — 메트로놈 위에 늦은 박스 도착 실측. Build-Up 포커스에 도착 업사이드.]','player_match_positions player_id=9; appearances Tielemans deep heatmaps','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(18,1,'2025-26',9,'CAM','자유 10번(좌편향): 박스 크리에이터가 아니라 라인 사이를 깊게 연결하는 메트로놈.','7선발 평균 7.24, 최고 8.4. 실측(포레스트 홈 7.9·어시스트): 90분 123터치 — 일반 10번의 거의 2배 볼륨. 좌편향 전장 배급.','컨트롤-10으로서 HIGH. 고전적 크리에이터의 박스 존재감은 없음.','빌라가 점유 지배를 예상하는 경기용 컨트롤 변형 10번(cam_playmaker/Build-Up 성향) 가용. 주 슬롯은 여전히 피벗.','player_match_positions player_id=9; appearances match_id=41 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(19,1,'2025-26',8,'pivot (all lanes)','더블 피벗의 박스투박스 쪽: 스크린·듀얼·박스 쇄도(헤더 득점). 파트너가 안 쓰는 레인을 가져간다.','사이드 불문: 중앙 15선발(평균 7.21·최고 8.1)/우 8(7.04)/좌 6(7.05) — 세 레인 산출 거의 동일. 연승기엔 카마라 좌측, 이후 틸레만스 우측. 중앙(맨시티 8.1)·좌(본머스 8.2)·우(뉴캐슬 원정 7.3) 실측 전부 같은 미드블록 스크린+박스 쇄도 패턴.','HIGH — 피벗의 만능 어댑터. 평점이 파트너 독립적.','dm_boxcrasher/Balanced 확인. 파트너 따라 LDM/RDM 자유 배치 — 수정 최적 XI는 카마라(RDM) 옆 LDM. [이벤트 스탯 2026-07-02: 긴장 — 최고 경기 기능은 박스크래셔(듀얼 6.6·공중 2.3·피벗 최저 패스량 37)이나 이 표본은 지배 편향 공유(시즌 최적은 dm_dlp/Roaming, 시즌 깊이 ~44).] [샷맵 2026-07-02: 슛의 35%가 헤더 — 박스 존재감은 대부분 세트피스 공중 도착. 박스크래시는 국면 한정, dm_dlp 오픈플레이 움직임과 양립.] [확정 2026-07-05: dm_holding/Roaming — 숙련도 타이브레이커(유일 숙련 DM). A/B 종결.]','player_match_positions player_id=8; appearances Onana heatmaps x4 (measured)','HIGH — full-season API position sweep.');
INSERT INTO player_duties VALUES(20,1,'2026-27',55,'LDM','영상·스카우트 분석 종합(가설): 캐리로 전진하는 B2B — 드리블 돌파보다 운반, 박스 침투 시 공중볼 위협, 중거리 슈팅, 롱스로 보유','클럽 실측: 딥 좌측 기본(좌2컬럼 50.4%), 태클 1.52·탈취 4.69/90 — 수비 기여 실재. 전진 배치는 대표팀에서만(전방 64.8%)','부분 일치 — 캐리 전진(온더볼)은 그리드 밖이라 미검증, 위치 주장은 실측이 정정','dm_dlp/Roaming 지지(캐리 전진형 딥롤). PlayStyles 확인 필요: 파워샷·긴스로인 보유 시 게임 재현 가산','obs#142 참조 (TFA·TransferFlow·X 스카우트)','서사+실측 교차검증 — 온더볼 주장만 가설 잔존');
INSERT INTO player_duties VALUES(21,1,'2026-27',58,'LM','영상 종합(가설): 컷인 후 파포스트 감아차기, 1v1 돌파·볼캐리, 카운터 위협','실측: 좌 편향(좌측 38경기), winger 커널 .771','정합 — 컷인형 윙어','wm_winger/Attack 유지. PlayStyles 확인: 감아차기·테크니컬·퀵스텝 보유(player_game_stats 2026-07-23 수집. ⚠️ 2026-08-11 교정: 종전 기재 ''트릭스터''는 수집값에 없음 — obs#143 근거에도 없는 미검증 기재였다)','obs#143','서사+실측 정합');
INSERT INTO player_duties VALUES(22,1,'2026-27',56,'LDM','영상 종합(가설): 볼위닝 destroyer + 박스 침투("6과 절반"), 프레스 저항 캐리, 약점 창의성','실측: 듀얼·태클 상위, dm_dlp/Roaming .763(위치 기준)','⭐ 긴장 — 위치는 dlp, 기능은 볼위너','dm_holding/Ball-Winning Δ 산출 후 처방 재검토(다음 세션)','obs#143','가설 — 커널 대조 대기');
INSERT INTO player_duties VALUES(23,1,'2026-27',57,'RCB','영상 종합(가설): 공중 지배(191cm)·후방 빌드업 개시·세트피스 골위협, CB/DM 겸업 가능','실측: cb_bpd/Aggressive .883 (29경기)','강정합','cb_bpd/Aggressive 유지. DM 겸업은 실측 표본 생기면 검증','obs#143','서사+실측 정합');
INSERT INTO player_duties VALUES(24,1,'2026-27',16,'ST','영상 종합: 뒷공간 런 리그 1위·박스 상주(채널 러너에서 진화), 양발+헤더 마무리, 전방 압박 탈취','실측: st_advanced 커널 정합, 상위 7경기 평점 8.47','강정합','st_advanced/Versatile 유지','obs#145','정합');
INSERT INTO player_duties VALUES(25,1,'2026-27',10,'RM','영상 종합: 명목 우측이나 움직임은 내부·수직(하이브리드), 듀얼 5.75/90 최다, 찬스 창출 최다, 중거리. 캐비앗: 피로 누적 시 수행 저하','실측: RM 21경기, wm_widemid/Support(뱅크 복귀) — 외부 분석이 obs#27·#89를 독립 재현','강정합 ⭐검증자 사례','wm_widemid/Support 유지','obs#145','정합');
INSERT INTO player_duties VALUES(26,1,'2026-27',8,'LDM','영상 종합: 공중볼 최강·듀얼 머신·인터셉트, 소유 유지형(창출 낮음), 딥 볼컨트롤 선호, 세트피스 위협(195cm)','실측: 피벗 29경기 평점 7.13, dm_holding/Roaming','강정합','dm_holding/Roaming 유지. 세트피스는 게임 공중볼 스탯으로 재현','obs#145','정합');
INSERT INTO player_duties VALUES(27,1,'2026-27',14,'CAM','영상 종합: 윙어가 아니라 플레이메이커 — 크로스 적음, 라인 사이 수신, 인필드 이동 후 중거리 드리븐','실측: 좌편향 자유 10번(부엔디아 좌측 실측이 기사 "우측 드리프트"를 정정한 원조 사례), cam_playmaker/Roaming','강정합','cam_playmaker/Roaming 유지','obs#145','정합');
INSERT INTO player_duties VALUES(28,1,'2026-27',3,'RCB','영상 종합: 태클 대신 포지셔닝·요격(passive-aggressive), 패스 95%, 약점 공중볼·크로스','실측: RCB 43경기 .943','강정합','cb_bpd/Aggressive 유지. 게임 공중볼 스탯 낮음 감안(세트피스 마킹)','obs#147','정합');
INSERT INTO player_duties VALUES(29,1,'2026-27',12,'RDM','영상 종합: 볼위닝+빌드업 겸장 — 짧은 연결과 프레스 위 클리핑 롱패스, 유의미 약점 없음','실측: 피벗 16경기 7.14','정합','dm_holding/Defend(RDM opt) 유지','obs#147','정합');
INSERT INTO player_duties VALUES(30,1,'2026-27',2,'RB','영상 종합: 윙어 출신 — 터프 태클+드라이브 전진 런의 공수 겸장','실측: RB, 처방은 C2 제약으로 의도적 잔류(fb_wingback/Balanced, obs#110)','정합(전진성은 구조가 봉인)','유지. 공격 전환 프리셋에서 att_wb 해방 검토 여지','obs#147','정합');
INSERT INTO player_duties VALUES(31,1,'2026-27',59,'RM','영상 종합(가설): 왼발 인버티드 — 우측 시작, 컷인 슛 개발 중, 전환·1v1 위협. 장기 프로젝트','실측: 그레미우 혼합 15경기, 커널 wm_widemid/Build-Up .833','⚠️ 방향 긴장 — 잠정','빌라 실측 6경기+ 축적 시 wm_insidefwd 대조 재판정','obs#147','가설 — 표본 부족');
INSERT INTO player_duties VALUES(32,2,'2026-27',63,'RB','우측 볼전진 수비수. 서사: 본직 라이트 CB이며 백3의 우측 또는 백4의 RB·인버티드 FB·DM까지 겸업하는 다역. 1페이즈에서 넓게 서다가 살짝 안으로 접히는 유형이며 전통적 상하 왕복 풀백이 ''아니다''라고 명시됨. 밀란전에서는 상대 레프트윙어(레앙) 대인 처리를 맡았다고 보도.','실측 1경기(밀란전 90분, 평점 7.6, hp=66): avg_x 43.0 · avg_y 24.4 → tool_x 75.6. CHE 슬롯 기하에서 RCB(x=66)와 RB(x=86) 사이 정중앙 — RCB에 근소하게 더 가깝다(9.6 vs 10.4). avg_x 43.0은 왕복형 풀백치고 낮다(같은 경기 Hato 43.5와 동급, Palestra 65.9와 대비).','MEDIUM — 서사의 ''넓게 섰다 안으로 접힘''·''왕복 풀백 아님''은 실측 tool_x 75.6(RB보다 안쪽)·avg_x 43.0(낮은 전진도)과 정합. 다만 백3 RCB인지 백4 RB인지는 **실측이 판별하지 못한다** — 두 슬롯 적합차 Δ.003.','⚠️ 슬롯 미확정: RB → fb_wingback/Support .638 / RCB → cb_bpd/Aggressive .635 (Δ.003, 구별 불가). 두 값 모두 .64 수준으로 낮은 것 자체가 하이브리드·경계 위치의 서명이다. pos_class=''RB''은 classify.py의 avg_x>35 문턱 산물이므로 신뢰 근거로 쓰지 말 것. 처방 변경 금지 — 표본 2경기+ 필요.','https://tacticalfootballanalysis.com/josh-acheampong-scout-report-at-chelsea-2025-2026-the-blues-next-defensive-leader-player-analysis/ ; https://instinctive.substack.com/p/scouting-josh-acheampong ; https://www.chelseafc.com/en/news/article/confirmed-chelsea-line-up-vs-western-sydney-wanderers','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ 1경기 표본. FBref 백분위 403 미확보. 신장 185cm vs 1.90m 소스 충돌. 알론소 체제 선발 지위도 소스 충돌(‘untouchable’ vs ‘두 형태 모두 선발 예상 안 됨’).');
INSERT INTO player_duties VALUES(33,2,'2026-27',65,'LDM','백라인 앞 딥 스크린. 서사: 단독 6번 또는 더블 피벗의 한 축이며 ''중앙을 거의 벗어나지 않는'' 규율형. 압박 저항이 반복 지명된 최대 강점. 밀란전에서는 모드리치 대인 마킹 임무. 본인 발언상 카이세도가 파괴자 역할을 분담.','실측 1경기(밀란전 90분, 평점 7.7, hp=77): avg_x 46.0 · avg_y 54.4(중앙 살짝 좌). 터치 68·리커버리 8·듀얼 4/6·패스 60중 58성공(96.7%) — 외부 보도의 동일 경기 수치(68터치·8리커버리·97%)와 독립 일치. ⭐ 이 경기가 첼시 입단 후 첫 90분 완주다.','HIGH — 서사의 ''딥 스크린 + 압박저항 + 라인 사이 배급''이 dm_dlp(딥라잉 플레이메이커) .913과 강정합. 정량 근거도 방향 일치: 라인 사이 패스 성공 4.57/90 PL 미드필더 1위·볼 상실 5.75/90 3번째로 적음(24/25). ''중앙 이탈 없음'' vs Roaming 포커스는 경미한 긴장이나 Δ가 노이즈 밖이라 적합 우선.','dm_dlp/Roaming .913 (2위 dm_dlp/Build-Up .798, Δ.115 — 노이즈 구간 밖). docs/30 4단계상 Δ>.05면 적합 우선 → Roaming 유지, 처방 변경 근거 없음(obs#144 고메스 선례와 동일 논리).','https://www.premierleague.com/en/news/4304480 ; https://transferhub.substack.com/p/scouting-report-what-makes-romeo ; https://totalfootballanalysis.com/player-analysis/romeo-lavia-at-southampton-scout-report-tactical-analysis-tactics ; https://chelsea.news/2026/08/xabi-alonso-chelsea-tactics/','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ 부상 이력이 지배적 캐비앗(24/25 선발 10회, 26-07 햄스트링). PFF 등급은 404로 검색 스니펫 경유 — 저신뢰. 피벗 구성도 소스 충돌(카이세도+엔소 예상 vs 실제 카이세도+라비아 선발).');
INSERT INTO player_duties VALUES(34,2,'2026-27',66,'LM','매우 높고 넓은 공격형 윙백. 서사: 본직은 **라이트** 백/윙백이며 양측면·백3 3번째 CB·인버티드 FB까지 되는 ''유니콘'' 다역. 1v1 고립을 의도적으로 부여받는 유형. 드리블 다량·양발 크로스가 핵심 무기.','실측 1경기(밀란전 90분, 평점 6.8, hp=47): avg_x 65.9 · avg_y 83.9 → tool_x 16.1. ⭐ **좌측 최외곽 + 매우 높은 전진도** — 서사의 ''우측 윙백'' 예측과 반대 측면이고, LM 슬롯(x=14)에 거의 정확히 앉는다. 키패스 3·터치 41.','MEDIUM-HIGH — 측면은 **실측이 서사를 기각**(우측 예측 → 좌측 실측, docs/30 3단계 ''위치 주장은 실측이 이긴다''). 높이·폭 주장은 실측 확인(tool_x 16.1·avg_x 65.9). 기능 주장(드리블·크로스)은 그리드 밖 층이라 가설 유지.','wm_widemid/Build-Up .888 vs wm_winger/Balanced .871 — **Δ.017, 노이즈 구간(≤.05)**. docs/30 4단계상 노이즈 구간에서는 서사가 이산 근거가 될 수 있다 → 서사(세리에A 성공 탈압박 2위·오픈플레이 크로스 9위·코너 획득 3위·의도적 1v1 고립)는 widemid보다 **wm_winger**를 가리킨다. 가설로만 기록 — 1경기 표본이라 처방 확정은 2경기+ 이후.','https://totalfootballanalysis.com/player-analysis/marco-palestra-scout-report-cagliari-2025-2026-analysis-tactics ; https://tacticalfootballanalysis.com/marco-palestra-scout-report-2026-2027-tactical-analysis-tactics/ ; https://breakingthelines.com/player-analysis/marco-palestra-one-of-the-biggest-prospects-in-italian-football/ ; https://www.skysports.com/football/news/11668/13557345/marco-palestra-to-chelsea-why-atalanta-wing-backs-dribbling-and-running-power-makes-him-a-fit-for-the-premier-league','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ 소스 내부 모순 다수: 공중볼을 ''강점''으로 쓴 리포트가 자기 수치로 48%를 제시(2월판은 51.4%를 약점으로 분류); 피지컬 지배력·리스크 성향도 소스간 정반대. 1경기 표본.');
INSERT INTO player_duties VALUES(35,2,'2026-27',67,'ST','베테랑 백업 9번. 서사: 데제르비 체제에서는 폴스나인, 휘르첼러 체제 24/25부터는 순수 центре포워드. 움직임의 핵심은 **내려받기** — 짧게 떨어져 CB를 끌어내 배후를 열고, CB-풀백 사이 하프스페이스에 위치. 압박의 기준점(프레스 리더)이며 등지고 받아 연결하는 역할.','실측 1경기(밀란전 58분, 평점 6.5, hp=18): avg_x **63.4** · avg_y 50.1(정중앙). ⭐ 같은 경기 João Pedro avg_x 74.3과 비교해 **10.9 낮다** — 서사의 ''내려받기''가 동일 경기·동일 상대 통제 조건에서 실측 확인됨. 터치 16·패스 5(4성공)로 관여량 자체는 낮다.','MEDIUM — ''드롭오프'' 위치 주장은 실측 강확인(동일 경기 내 ST 두 명 전진도 대조). 다만 ⚠️ hp=18로 그리드 유효 문턱(15, docs/30 ③)을 겨우 넘겨 그리드 형태 신뢰도는 낮다.','st_advanced/Support .570 (2위 st_false9/Build-Up .420, Δ.150). 서사가 암시한 폴스나인 역할은 커널상 명확히 열세 — 내려받기는 **역할(false9)이 아니라 포커스(Support)+낮은 avg_x로 재현**된다. 적합 .570 자체가 낮아 처방 근거로 쓰기 부족. 표본 축적 필요.','https://www.skysports.com/football/news/11668/13568440/chelsea-transfer-news-danny-welbeck-completes-move-to-stamford-bridge-from-brighton-for-undisclosed-fee ; https://www.beinsports.com/en-us/soccer/premier-league/articles/why-did-xabi-alonso-s-chelsea-sign-veteran-danny-welbeck-2026-08-01 ; https://totalfootballanalysis.com/team-analysis/brighton-fabian-hurzeler-build-up-tactical-analysis-tactics ; https://www.premierleague.com/en/news/4171172','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ **26/27 첼시 역할을 다룬 전술 소스가 없다** — 스타일 서술 전량이 브라이턴 시절(2024~2026). 35세·단기 계약. hp=18 경계 표본. 첼시 내 비중도 소스 충돌(depth 옵션 vs ''핵심 역할'').');
INSERT INTO player_duties VALUES(36,3,'2026-27',69,'RCB','전방지향 센터백. 서사: 198cm 장신이며 ''전개되기 전에 공격을 차단하는'' 선제형. 공중볼 지배(오픈플레이·세트피스 양방향), 장신 대비 리커버리 스피드 양호. 우측 CB 주장과 3-5-2 중앙 CB 주장이 병존.','실측 1경기(모나코전 45분 선발, 평점 6.7, hp=36): avg_x 31.6 · avg_y 27.6 → tool_x 72.4(RCB 슬롯 x=63보다 우측). 판 다이크(좌, tool_x 34.2)와 짝 — 우측 배치 서사와 정합. 태클 3·클리어 3·패스 24중 23성공.','MEDIUM — ''전방지향·선제 차단'' 서사는 **Aggressive 포커스**(=스텝업 요격, obs#147 콘사 선례)와 정합. 우측 CB 주장도 실측 확인(tool_x 72.4). 3-5-2 중앙 CB 주장은 이 표본에서 기각.','cb_bpd/Aggressive .803 (2위 cb_bpd/Build-Up .726, 3위 cb_stopper/Aggressive .663 → bpd 대비 Δ.140). ⚠️ 서사의 ''전진 패스 의문·짧고 단순한 패스'' 주장은 bpd(배급형)와 긴장 관계이나, Δ.140은 노이즈 밖이므로 **적합 우선 — bpd 유지**. 패스 품질 의문은 역할이 아니라 스탯·PlayStyles 층에서 재현할 사안(obs#144와 동일 논리).','https://anfieldinsights.substack.com/p/why-liverpool-are-signing-ifeanyi ; https://www.thisisanfield.com/2026/01/who-is-ifeanyi-ndukwe-liverpool-transfer-fee-style-quotes/ ; https://www.thisisanfield.com/2026/07/liverpool-ifeanyi-ndukwe-work-permit-ineligible-iraola/','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ **저신뢰**: TFA·Coaches Voice·Opta·breakingthelines 어디에도 전용 필름 분석이 없다 — 서브스택 1건·Tribuna 블로그 1건·구단 팬포럼 인용이 전부. 인용 수치(인터셉트 6/90 등)는 CB 기준선(~1.5) 대비 비현실적이라 **기록하지 않았다**. ⛔ 별건 중대: 26/27 취업허가 미달로 리버풀 출전 불가 — obs 참조.');
INSERT INTO player_duties VALUES(37,3,'2026-27',70,'LB','오버래핑 레프트백. 서사: ''넓고 높게'' 서며 오버랩·언더랩 모두 가능, **인버트하지 않는다**. 엘리트 크로스가 핵심 무기. 이라올라 체제 풀백 브리프도 인버트가 아니라 오버랩 — 윙어+풀백의 측면 과부하(''double threat'')와 풀백의 전진 오버랩.','실측 1경기(모나코전 59분 선발, 평점 6.2, hp=52): avg_x **42.1** · avg_y 80.4 → tool_x 19.6(LB 슬롯 x=13보다 안쪽). 리커버리 8·태클 2. 크로스 관련 산출 없음(키패스 0).','MEDIUM — ''넓게''는 실측 확인(tool_x 19.6, 좌측 외곽). ⚠️ ''높게''는 **이 표본에서 확인되지 않는다** — avg_x 42.1은 중간 높이이며 같은 경기 Frimpong(우, 53.4)보다 11.3 낮다. 인버트 부재는 실측 정합(안쪽으로 들어온 흔적 없음).','fb_wingback/Balanced .741 (2위 fb_fullback/Balanced .727) — **Δ.013, 노이즈 구간**. 서사(오버랩·크로스량·측면 과부하)는 fullback보다 wingback을 지지하므로 커널 선택과 방향 일치 — 노이즈 구간이나 서사가 같은 쪽을 가리켜 유지. 높이 주장이 실측과 어긋나므로 Attack 계열 포커스로의 상향은 근거 없음.','https://totalfootballanalysis.com/article/scout-report-kostas-tsimikas-2019-20-tactical-analysis-tactics ; https://tacticalfootballanalysis.com/andoni-iraola-tactics-liverpool-2026-2027-tactical-analysis/ ; https://www.thisisanfield.com/2026/05/kostas-tsimikas-liverpool-stay-next-season-plans-2026/ ; https://www.liverpoolfc.com/news/kostas-tsimikas-return-liverpool-what-iraola-wants-and-squad-mood','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ **정량 근거가 6년 낡았다** — TFA 리포트가 2019/20 올림피아코스 데이터(크로스 34%·수비듀얼 60.6% 등). 로마 25/26 감독 평가는 ''다재다능하지 않다''로 TFA의 오버랩·언더랩 겸용 주장과 상충. 26/27 잔류 여부 소스 충돌(4~6월 잔류 → 8월 이탈 예상) — 단 실측상 08-09 출전으로 현재 스쿼드 내 존재는 확정.');
INSERT INTO player_duties VALUES(38,3,'2026-27',71,'RM','전방 압박형 와이드 어태커. 서사: DB 표기는 좌측 윙어(오른발 인버티드)이나 **본인은 ''중앙 9번이 가장 효과적''이라 주장**하며, 이라올라 프리시즌에서 폴스나인으로 썼다는 보도가 있다. 전방 압박이 리버풀 스타일에 맞는 강점으로 지명됨.','실측 1경기(모나코전 75분 선발, 평점 6.4, hp=40): avg_x 64.3 · avg_y 25.2 → tool_x **74.8**. ⭐ **우측 와이드 + 전진** — 중앙이 아니다. 슛 4·키패스 1·리커버리 7. 동일 경기 Ngumoha는 31분 교체 출전(45분 미달로 본 수집 대상 외)이므로, ''응구모하 우측·쿠마스 중앙'' 보도는 후반 교체 이후 국면을 서술한 것으로 보인다.','LOW(서사) / HIGH(실측) — ⛔ **위치 주장 기각**. 같은 경기(모나코전)를 근거로 한 ''중앙 폴스나인'' 보도와 본인의 ''중앙 9번'' 자기평가가 실측 tool_x 74.8·75분과 정면 충돌한다. docs/30 3단계·CLAUDE.md 규칙 3에 따라 **실측 채택** — 만잠비 ''추가 스트라이커'' 기각과 동형 사례. 압박 기여 주장은 그리드 밖 층이라 가설 유지(리커버리 7로 방향은 지지).','wm_winger/Balanced .720 (2위 wm_widemid/Build-Up .678) — Δ.042, 노이즈 구간. ⚠️ 서사의 기능 지표는 winger 역할과 **역방향**이다(드리블 성공 25%·듀얼 32.8%·찬스창출 6번째 백분위). 위치는 와이드로 확정이나 역할 품질 근거가 약하므로 처방 확정 보류 — 위치(확정)와 역할(보류)을 분리해 기록.','https://www.thisisanfield.com/2026/07/lewis-koumas-liverpool-no-9-andoni-iraola/ ; https://www.fotmob.com/players/1364042/lewis-koumas ; https://footystats.org/players/england/lewis-koumas ; https://www.thisisanfield.com/2026/08/lewis-koumas-wanted-by-several-clubs-loan-likely-despite-good-pre-season/','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ 필름 분석 소스 없음 — 뉴스·본인 인터뷰·DB 백분위가 전부. 백분위는 FBref가 아니라 FotMob(챔피언십 833분 스냅샷). 26/27 임대 유력 보도.');
INSERT INTO player_duties VALUES(39,3,'2026-27',72,'ST','단독 9번·득점 초점. 서사: 라벨 분쟁이 있다 — ''다이내믹 포처''로 부르는 리포트와 ''중앙만큼 좌우로도 빠지고 카운터 개시를 위해 깊게 내려온다''는 서술이 **같은 소스 안에서** 병존. 공통분모는 박스 고정형이 아닌 하이브리드. 압박의 첫 단계이며 커브 런으로 패스 차단(이라올라의 터치라인 유도와 부합). 비르츠를 위한 디코이 러너.','실측 1경기(모나코전 59분 선발, 평점 7.1, hp=**25**): avg_x 72.7 · avg_y 53.1(중앙). 골 1·어시 1·슛 1·키패스 2·터치 23. hp=25로 그리드 포인트가 적다.','MEDIUM-LOW — 전진도(72.7)·중앙성(53.1)은 확인되나 hp=25·59분으로 좌우 이탈 폭을 판정할 해상도가 없다. ''하이브리드 vs 포처'' 라벨 분쟁을 이 표본으로 해소할 수 없다.','⭐ st_poacher/Support .7659 ≡ st_advanced/Attack .7659 — **커널 그리드가 동일해 완전 동률**이며, 구별되는 3위(st_poacher/Versatile .737)까지 Δ.029로 노이즈 구간. 즉 **소스가 못 정한 라벨(포처 vs 전진형 하이브리드)을 커널도 기계적으로 못 정한다** — 우연이 아니라 두 역할의 커널이 같기 때문. 역할 확정 불가, 처방 보류. 표본 축적이 유일한 해소 경로.','https://www.premierleague.com/en/news/4407886/analysis-how-isaks-introduction-could-impact-liverpools-frontline ; https://totalfootballanalysis.com/recruitment-analysis/alexander-isak-hugo-ekitike-scout-report-2025-2026-liverpool-recruitment ; https://breakingthelines.com/player-analysis/player-analysis-alexander-isak/ ; https://thepfsa.co.uk/analysis-what-liverpool-might-look-like-under-andoni-iraola/','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ hp=25 저해상도 1경기. 소스간 패스 정확도가 54.76% vs 75.3%로 미조정 충돌. 약점 정량: 듀얼 성공 35%·인터셉트 0.1/90 — 홀드업 요구가 큰 시스템에서 리스크. 25/26 부상으로 22경기 4골.');
INSERT INTO player_duties VALUES(40,3,'2026-27',73,'GK','리액티브 샷스토퍼. 서사: 스위퍼형이 아닌 전통형이며 **골라인 근처에 머무는 성향**이 명시적으로 지적된다 — 라 리가 23/24 스위핑 0.41회/경기. 배급은 한발·레인지 제한(발렌시아 스타일 탓이라는 반론 있음)이나 스로 배급은 우수. 박스 장악·크로스 차단은 강점. ⚠️ 하이라인 뒤에서의 리스크로 지목됨.','실측 1경기(모나코전 후반 45분 교체, 평점 7.2, hp=32): avg_x **8.6**. ⭐ **동일 경기 통제 비교**: 전반 45분을 뛴 알리송은 avg_x 15.8 — 마마르다슈빌리가 **7.2 더 깊다**. 세이브 3·패스 23중 21성공.','HIGH — ''골라인 고착'' 서사가 동일 경기·동일 상대·각 45분이라는 준통제 조건에서 실측 확인됨. 커널 포커스도 갈린다: 알리송 gk_goalkeeper/**Balanced** .972 vs 마마르다슈빌리 gk_goalkeeper/**Defend** .957. ⚠️ 교란요인 명기: 알리송은 리드·동점 국면(lead 29'')만 뛰었고 마마르다슈빌리는 2-1→2-3 붕괴 국면(level 32''·trail 2'')을 뛰었다 — 피격 상황이 GK를 뒤로 밀 수 있으므로 7.2 전량을 성향으로 귀속하지 말 것.','gk_goalkeeper/Defend .957 (2위 Balanced .922, Δ.035 — 노이즈 구간). 노이즈 구간이지만 서사(스위핑 0.41/경기·라인 고착)가 Defend를 독립 지지하므로 docs/30 4단계상 서사를 이산 근거로 채택 가능. ⭐ 전술적 함의: 이라올라는 하이라인을 쓰는데 이 GK는 라인을 비우지 않는다 — **GK 교체가 곧 라인 리스크 변경**이므로 알리송/마마르다슈빌리를 같은 처방으로 묶으면 안 된다.','https://transferhub.substack.com/p/scouting-report-giorgi-mamardashvili ; https://www.premierleague.com/en/news/4431976/analysis-how-liverpool-will-miss-alisson-and-who-is-mamardashvili ; https://www.espn.co.uk/football/story/_/id/46615423/liverpool-giorgi-mamardashvili-alisson-georgia-premier-league-arne-slot-goalkeeper ; https://www.empireofthekop.com/2026/06/11/andoni-iraolas-liverpool-blueprint-pressing-direct-attacks-and-a-clearer-identity/','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ 이라올라 하이라인 하에서의 전용 분석은 없다 — ''하이라인에 맞지 않는 GK'' 발언은 애널리스트가 아니라 팬 코멘트이므로 근거로 쓰지 않았다(실측이 대체). No.1 지위는 미해소 3방 충돌(마마르다슈빌리 기회 vs 임대 추진 vs 알리송 선발). PL 비교 수치는 백업 전체 풀이라 개인 귀속 불가.');
INSERT INTO player_duties VALUES(41,3,'2026-27',74,'RDM','수비 우선 딥 6번. 서사: 공중볼 지배(2020/21 이후 분데스리가 미드필더 중 공중 듀얼 최다 승리), 듀얼·볼 회수량 최상위(Opta: 분데스리가 미드필더 중 듀얼 1위·소유권 획득 2위·태클 2위). 다만 **스텝업도 한다** — 22/23 리커버리의 39.5%가 상대 진영에서 나왔다.','실측 1경기(모나코전 후반 45분 교체, 평점 6.2, hp=54): avg_x **22.5** · avg_y 31.8 → 매우 깊다. 패스 40중 33성공·리커버리 4·클리어 1. 국면 확인: lead 11'' · level 32'' · trail 2'' — **리드 방어가 주 국면이 아니므로** 깊은 위치를 국면 탓으로 돌릴 수 없다(교란요인 배제).','MEDIUM-HIGH — ''수비 우선 딥 6번''은 실측 강정합(avg_x 22.5는 이번 회차 미드필더 중 최저). ⚠️ 서사의 ''상대 진영 리커버리 39.5%'' 스텝업 주장은 **이 표본에서 확인되지 않는다** — 다만 45분 교체 1경기라 기각도 아니다(보류).','dm_holding/Defend .879 (2위 dm_holding/Ball-Winning .844) — **Δ.035, 노이즈 구간**. 서사의 정량(듀얼 1위·소유권 획득 2위·공중볼 최다)은 Defend보다 **Ball-Winning**을 가리키므로 docs/30 4단계상 노이즈 구간에서 서사가 이산 근거가 될 수 있다. 역할(dm_holding)은 양쪽 동일해 확정, 포커스만 Defend/Ball-Winning 미결 — 표본 축적으로 해소.','https://totalfootballanalysis.com/player-analysis/wataru-endo-at-liverpool-fc-2023-24-scout-report-tactical-analysis-tactics ; https://www.planetfootball.com/quick-reads/wataru-endo-liverpool-profile-scouting-report-defensive-midfield-signing ; https://one-versus-one.com/en/players/wataru-endo ; https://www.footballinsider247.com/liverpool/sources-liverpool-plan-to-accept-wataru-endo-offer','서사 소스(3티어급) — 가설 지위(docs/30 영상·서사 절차 2단계). 위치 주장은 실측 우선. ⚠️ **26/27 전술 분석이 전무하다** — 전량 슈투트가르트 22/23 및 리버풀 23/24 데이터(3~4년 낡음). 듀얼 볼륨은 소스 충돌 미조정(Opta 분데스 1위 vs TFA 수비듀얼 시도 50백분위 미달 — 정의 차이 추정). 33세이며 이적 시장에 올라 있음 — obs 참조.');
INSERT INTO player_duties VALUES(42,1,'2025-26',75,'DM','토트넘(프랭크) 25/26 임대에서 클래식 볼위닝 앵커/6번 — 백라인 스크린, 전환 지연, 세컨드볼 회수, 중앙 진입로 차단. TFA는 프랭크가 브렌트포드의 뇌르고르 역할(순수 볼위너 + 세트피스 빅바디, 190cm·풀럼 시절 공중듀얼 62%)로 기용했다고 분석. PL 5번째로 많은 팀 내 출전시간 — 로테이션이 아닌 중심 기둥. 온볼 배급은 엘리트가 아니라는 한계 병기(풀럼 2년 태클 300개 1위·경고 27장의 파울 비용).','DB 실측과 정합: transfer_targets.map25(002112323345365465X611221) — X가 자기진영 중앙(행3)·중심 툴좌표(53.7, 44.0)로 중앙 저지대 편중 = 앵커 서사 그대로. opt_role dm_holding/Ball-Winning(숙련 일치, DB rationale의 FC26 확인: DEF83/PHY84/공격성91/태클85·브루저)이 서사의 볼위닝 정체성과 일치. 표본 6경기 평균 6.92.','HIGH — 서사(볼위닝 앵커·중앙 스크린)와 실측 그리드·기능축이 전면 정합. 긴장은 슬롯 커널 층에서만 발생: 빌라 LDM 기용 시 fit dm_widehalf/Build-Up .709, RDM 시 dm_dlp/Roaming .738 — 본인 정체성(dm_holding)과 슬롯 최적역할이 갈린다.','dm_holding/Ball-Winning — 에메리 더블 피벗 처방(dm_holding Roaming/Defend 분담)과 정확 일치, 카마라·보가르드 동형. LDM 투입 시 커널 지불(.709)은 감수 항목. 네거티브 PS ''부상에 취약함''(DB 확인) 로테이션 설계 필요.','Total Football Analysis — totalfootballanalysis.com/player-analysis/joao-palhinha-scout-report-tottenham-hotspur-2025-2026-analysis-tactics · BBC Sport — feeds.bbci.co.uk/sport/football/articles/cdj2ygpp42ko','서사 소스(3티어급) — TFA 스카우트 리포트는 25/26 시즌 발행 확인(제목 명기). 실측 표본 6경기(45분+)로 시즌 전수 아님.');
INSERT INTO player_duties VALUES(43,1,'2025-26',76,'ST','바이에른(콤파니) 25/26 임대(€16.5m, 조건부 옵션 €65m)에서 케인 백업·로테이션 ST. 바이에른 공식 프로필: ''클래식 박스 스트라이커가 아니라 딥존에서 동력을 발동 — 등지고 지켜 원터치 레이오프, 파워 스트라이드로 미드필드와 가교''. 압박 개시·하이 리커버리가 백업 적합 사유로 분석됨(Goal). 시즌 궤적: 분데스 첫 6경기 무득점 → AFCON(세네갈 우승) 복귀 후 99분 주변부 → 4월 기준 9골 4도움으로 회복, 분데스리가 우승 스쿼드.','DB 실측과 정합: map25(457725X496434211211100000) — X가 공격 2행째 중앙-좌, 전진 질량 압도 + 하강 링크 꼬리. fit=opt=st_advanced/Support .752 — Support 포커스가 ''딥존 발동·레이오프'' 서사와 정확 대응(DB rationale도 ''하강 링크 성향(실측)'' 명기). 표본 6경기 평균 7.45 — 8명 중 최고.','HIGH — 바이에른 공식·외부 분석의 ''링크형 9번'' 서사와 실측 Support 포커스가 정합. 긴장 1건: 서사의 ''마무리 불안정''(첫 6경기 무득점)은 평점 실측(7.45)에는 안 보임 — 표본이 폼 회복기(후반기)에 몰렸을 가능성.','st_advanced/Support 유지 — 왓킨스와 로테이션 축. DB 확인 PS 게임체인저·테크니컬이 Support 링크 역할과 부합. 박스 피니셔(st_target류) 재해석은 실측 근거 없음.','FC Bayern 공식 — fcbayern.com/en/news/2025/09/nicolas-jackson-bayern-new-signing-with-street-football-in-his-blood · Bavarian Football Works — bavarianfootballworks.com/bayern-munich-opinion/185121 · Goal — goal.com (Kompany fit 분석·복귀 전망 기사 2건)','서사 소스(3티어급, 단 바이에른 공식 프로필은 1차 출처) — 25/26 시즌 내 발행 확인. 실측 표본 6경기, 후반기 편중 가능성 캐비앗.');
INSERT INTO player_duties VALUES(44,1,'2025-26',77,'RW/CAM','팔메이라스(아벨 페레이라)에서 왼발 인버티드 윙어 — 우측면에서 안으로 감아드는 유형(ScoutingStats 분류). 브라질 기자 Filipe Guedes: ''강하고 빠르고 다재(양 윙·공미·중미 소화), 기술적이며 또래답지 않게 전술적으로 성숙, 오프더볼 활동량''. ''더 강한 하비 엘리엇'' 비유(Rousing The Kop, 2026-02). WhoScored 모델: 드리블 Very Strong·공중듀얼 Strong, 크로스·규율(경고/퇴장)이 약점. 2026 세리이A 4골 2도움·팟몹 평균 7.25, 리베르타도레스 1골 2도움. 득점력은 아직(통산 64경기 5골).','DB 실측과 대체로 정합: map25(001361125X001360013500001) — X 공격 2행째 우측, 중심(77.2, 59.4) 우측·전진 편향 = 우측 인버티드 서사 그대로. 평균 7.18(최고 8.4)도 팟몹 7.25와 상응. 단 ''공미 겸용'' 서사는 실측 CAM 적합 .674 급락으로 기각 — 등재 슬롯 RM이 맞다(DB 판정과 동일). W군 재채점 w_wideplm/Build-Up .870 = 해방 윙어 풋프린트.','MEDIUM-HIGH — 우측·컷인사이드·활동량 서사는 실측 정합. 다포지션 서사 중 CAM 주장은 실측이 기각(위치 주장은 실측 우선). 크로스 약점 서사는 실측 그리드와 무충돌(검증 불가 항목).','wm_winger/Balanced(RM .812 — 하지무사 .821·은디아예 .825와 동급)이되, 에메리 구조에서 RM은 뱅크 칸이라 실기용 시 wm_widemid/Support .734 지불(−.078). 좌측이 이미 해방 우세인 현 스쿼드에서 구조적 긴장 — 해방 사이드용 자원이라는 DB 판정을 서사(오프더볼 성실)가 일부 완화하지만 뒤집지는 못함.','Rousing The Kop — rousingthekop.com/2026/02/20/allan-elias-scout-report-why-liverpool-could-be-looking-to-sign-the-next-harvey-elliott/ · WhoScored — whoscored.com/players/521094/show/allan · FotMob — fotmob.com/players/1721789/allan','서사 소스(3티어급) — 2026-02 발행 확인(본문 21세 표기 = 2004년생 정합). 리버풀 우선매수권 보도(2026-02)는 DB 08-09 최신화(빌라 최선두·셀링클럽 블록)와 병존 — 경쟁 실체 신호로만 기록. 실측 표본 6경기.');
INSERT INTO player_duties VALUES(45,1,'2025-26',78,'LB','아틀레티코(시메오네) 25/26 — 갈란 대안으로 €17m+α 영입된 주전급 LB. 서사 일치점: 오버랩·좌측 폭 제공이 트레이드마크, 크로스 볼륨(리그 95회·찬스 25회·키패스 22), 전진 패스 상위(톱5리그 LWB 중 progressive passes 81퍼센타일), 공중듀얼 강점, 침착한 수비 리딩. 가스페리니 백3 윙백 출신의 백4/윙백 겸용 다재. 약점: 1대1 수비 다듬기, 공격 마무리(시즌 슛 4회·xG 0.36). 26 La Liga 출전(20선발 1,957분) 0골 3도움 + UCL 로테이션.','DB 실측과 정확 정합: map25(32100X2000410007200031000) — X 공격행 좌측 터치라인, 좌측 레인 수직 분포 = 오버랩 서사 그대로. fit fb_att_wb/Support .949(2위 대비 Δ.214 단독 1위), 에스투피냔 .946과 동급 프로필. 표본 6경기 평균 6.77 — 수비수 평점 기저 감안 필요.','HIGH — 오버랩·크로스·전진패스 서사와 전진형 LB 그리드가 전면 정합. 캐비앗: 서사의 ''수비 솔리드''는 그리드로 검증 불가, xG 0.36은 Support(Attack 아님) 포커스 판정을 지지.','fb_att_wb/Support — 에메리 C2 비대칭(좌전진 LB)과 정확 일치, 디뉴 공백 1:1 대체. FC26 존재(77/83, best LB) — PS 휩 패스가 크로스 서사와, 에어리얼 포트리스가 공중듀얼 서사와 각각 부합.','Total Football Analysis — totalfootballanalysis.com/player-analysis/matteo-ruggeri-scout-report-atletico-madrid-2025-2026-analysis-tactics · Into the Calderon — intothecalderon.com/atletico-madrid-columns/24965 · ScoutingStats — scoutingstats.ai/player/matteo-ruggeri-24837941/','서사 소스(3티어급) — TFA 25/26 리포트·시즌 종료 후 평가 기사로 시점 검증됨. 실측 표본 6경기(5월 라리가 4 + UCL 2)로 시즌 후반 편중.');
INSERT INTO player_duties VALUES(46,1,'2025-26',15,'WM','빌라 25/26(맨유發 임대, ~2026-05-31) — 베일리 공백 보강. 서사: 순수 스피드가 아닌 짧은 콤비네이션·타이트 컨트롤·타이밍으로 창조하는 와이드 크리에이터, 러너와의 연계·박스 에지 공략이 최대 무기. 시즌 평가는 실망 — 35경기 1골 3도움(PL 23경기 9선발, 평균 ~45분), 볼로냐 EL 2연전 스쿼드 제외, 맥긴·부엔디아·로저스에 밀린 벤치 자원. 단 언더라잉 지표는 양호했다는 재평가(astonvillanews 2026-05-30) + 에메리가 완전영입에 열려있다고 발언(ESPN).','DB 실측과 부분 정합: 상위 3경기 평균 7.33(measured 그리드는 RW, X 좌중앙행)·시즌 그리드(74134X6346...)는 좌측 전방 피크 — 우측 고정이 아니라 양 측면 로테이션(DB도 ''린델뢰프/산초 rotation'' 명기). ''창조'' 서사는 kp 2.5/경기(상위 경기 표본)와 정합, ''낮은 생산'' 서사는 시즌 1골 3도움과 정합 — 상위 표본과 시즌 전수의 괴리가 그의 시즌 요약이다.','MEDIUM — 스타일 서사(연계형 창조자)는 정합하나 ''우측 윙어'' 위치 서술은 실측이 양측 사용으로 교정(위치 주장은 실측 우선). 일관성 결여 서사가 top3 7.33 vs 시즌 벤치 신세의 진폭과 정확히 상응.','w_insidefwd/Attack 벤치 처방(왼발 인버티드 RW — 상위 경기 7.5/7.4/7.1 근거) 유지가 타당. 서사도 주전 재료 아님을 지지 — 임대 만료(05-31) 후 지위는 transfer 트래킹 사안.','Aston Villa News — astonvillanews.co.uk/2026/05/30/jadon-sancho-was-close-to-aston-villa-stardom-in-2025-26-the-numbers-prove-it/ · ESPN — espn.com/soccer/player/_/id/259836/jadon-sancho · LiveScore 25/26 시즌 스탯','서사 소스(3티어급) — 2026-05-30 시즌 결산 기사로 최신성 확보. 실측 상위 3경기 표본은 선별 편향 명기 필요.');
INSERT INTO player_duties VALUES(47,1,'2025-26',7,'CB','빌라 25/26(2025-09-01 자유이적) — 뎁스 CB. 서사: 17경기 945분(11선발), 로테이션 자원으로 듀얼 18-11·공중 11-6 우위, 무실책 안정형(커리어 211경기 무퇴장), 마지막 경기(맨시티전 73분, 7.2)도 견실. 시즌 평점 소스별 6.52(팟몹)~6.79(StatMuse). EL 우승 스쿼드 기여.','DB 실측과 정합: squad_entries rate 7.05(상위 4경기)·v_profile 5경기 6.88, 양쪽 CB 커버. 시즌 그리드(0001203126249762X9X727665) 자기진영 중앙-우 이중 피크 = RCB 기본. optimal은 LCB cb_bpd/Aggressive — 스텝아웃 실측(시즌그리드 .826)이 근거로, ''리딩·스텝인'' 서사와 방향 일치.','HIGH — 뎁스·안정·듀얼 우위 서사와 실측 평점·그리드 정합. 서사에 실측과 충돌하는 위치·스타일 주장 없음.','cb_bpd/Aggressive(LCB 예비) + dm_holding/Defend(RDM 비상 — 리버풀전 실증) 유지. 로테이션 CB 이상을 시사하는 서사 없음 — 처방 변경 근거 부재.','LiveScore — livescore.com/en/season-stats/victor-lindelof/27767/ · StatMuse — statmuse.com/fc/player/victor-nilsson-lindelöf-6430 · FotMob — fotmob.com/players/258269','서사 소스(3티어급, 통계 집계 사이트 위주 — 전술 서사 매체의 단독 분석은 미발견) — 25/26 시즌 데이터 명기. 실측 표본 5경기(360분)로 얇음.');
INSERT INTO player_duties VALUES(48,1,'2025-26',11,'DM/FB','빌라 아카데미 출신(2020 페예노르트發) 다포지션 유틸리티 — DM 스크린·볼 재순환, CB 리딩·커버, RB에서 안으로 접어 백3 형성 등 ''스위스 아미 나이프'' 서사. 25/26 PL 7선발 665분·팟몹 6.39·경고 5. 11월 U21 대표팀에서 ''unfit'' 사유 제외. 시즌 결산 비판(astonvillanews 2026-05-31): ''다재 기여는 인정하나 본 포지션(DM)에서 길을 잃은 듯했고 성장 여지 지표가 빈약'' — 선덜랜드 관심 보도.','DB 실측과 정확 정합: pos_class별 그리드가 다포지션 서사를 정량 입증(피벗우 18경기·피벗중 3·피벗좌 1·RM/AMR 1 + RB 8선발 704분 별도 슬롯). 피벗 21경기 평균 6.62·RB 6.46은 팟몹 6.39와 상응 — ''임팩트 부족'' 비판과 평점 실측 일치. 기능축은 볼위닝(듀얼 5.8·인터셉트 1.8·xa .03).','HIGH — 다포지션·저임팩트 서사 모두 실측이 뒷받침. 유일한 뉘앙스: 시즌 최근접 역할은 dm_dlp/Roaming .790으로 ''순수 스크린'' 서사보다 이동 반경이 넓다 — 실측 우선.','dm_holding/Ball-Winning(RDM, 카마라 동형) + fb_wingback/Balanced(RB .832) 겸용 유지. 서사의 성장 한계론 + 선덜랜드 링크는 스쿼드 플래닝(팔리냐 영입 시 서열 하락) 참고 사항.','Aston Villa News — astonvillanews.co.uk/2026/05/31/lamare-bogarde-may-have-already-shown-true-potential-at-aston-villa-his-best-isnt-good-enough/ · FotMob — fotmob.com/players/1190033/lamare-bogarde · avfc.co.uk/players/lamarbogarde/','서사 소스(3티어급) — 2026-05-31 시즌 결산으로 최신성 확보. 실측은 피벗 18경기로 8명 중 가장 두꺼움.');
INSERT INTO player_duties VALUES(49,1,'2025-26',60,'ST','베식타시 임대 13골(26경기) 후 2026-01-27 빌라 완전 복귀(€21m, 2030 계약) — 에메리 공식 발언 ''왓킨스와 공격 3선 경쟁·공존''. TFA 스카우트 리포트 서사: 박스 스트라이커 — CB 사이 공간 공략, 라인 크로스 침투, 중앙 마무리, 상대 박스 터치·골기여·공중듀얼 상위(팟몹 퍼센타일: 득점 82·찬스창출 65·수비기여 71·공중 55). 합류 후 반 시즌 3골(리즈전 88분 극장 동점골 등) — 언더라잉은 양호, 26/27 풀 프리시즌 후 도약 기대 서사.','DB 실측과 긴장: measured(25경기 전수, n=25·1878분·평균 6.95) 그리드(239324777256X732212211410)는 X가 중앙 3행(미드필드)·하강 질량이 커서 st_false9/Attack(fit .643)이 argmax — TFA의 ''박스 스트라이커'' 서사와 어긋난다. 단 xg .508/경기·dw 2.92는 박스 위협·공중 서사를 지지 — 온볼 이벤트는 박스형, 이동 풋프린트는 하강형인 이중 프로필.','MEDIUM — 위치 풋프린트 주장은 실측(false9형 하강)이 이긴다. 득점·공중 산출 서사는 실측 스탯과 정합. ''박스 전용'' 단정은 기각, ''박스 마무리 + 하강 연계 병행''으로 종합.','fc26:opt는 st_target/Attack(v1 이관)이나 실측 argmax는 st_false9/Attack(.643) — 둘 다 낮은 적합이라 26/27 표본 축적 후 재판정 대상. TFA 서사(라인 침투·공중)는 st_target 쪽을, 실측 그리드는 false9 쪽을 각각 지지 — 처방 충돌 미해소 상태로 기록.','Total Football Analysis — totalfootballanalysis.com/player-analysis/tammy-abraham-scout-report-aston-villa-2025-2026-analysis · avfc.co.uk 공식 발표(2026-01-27) · Aston Villa News — astonvillanews.co.uk/2026/06/03/tammy-abraham-aston-villa-star-shows-2026-27-breakout-potential-with-underlying-numbers/','서사 소스(3티어급, 클럽 공식 발표는 1차) — 2026-01~06 발행 검증. 실측 25경기는 로마·밀란기 포함 여부 확인 필요(notes상 26/27 스쿼드 실측 명기).');
